package com.example.course.controller;

import com.example.course.dto.CourseResponse;
import com.example.course.service.CourseBookmarkService;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;

/**
 * 과정 즐겨찾기 관련 API를 제공하는 컨트롤러
 */
// SFR-113 : 강의 즐겨찾기 기능 Test Case
//   **즐겨찾기 편집 및 등록**
//    - 즐겨찾기에 대한 조회, 추가, 삭제 기능 제공(O)
//   **즐겨찾기한 강의에 대한 간략한 정보 조회**
//    - 강의 기간, 레벨, 강사 정보 등을 간략하게 조회할 수 있는 정보 제공
//  
@RestController
@RequestMapping("/api/v1/bookmarks")
@RequiredArgsConstructor
public class CourseBookmarkController {

    private final CourseBookmarkService bookmarkService;

    /**
     * 현재 사용자의 즐겨찾기 과정 목록 조회
     * @param authentication 인증 정보
     * @return 즐겨찾기한 과정 목록
     */
    @GetMapping("/courses")
    public ResponseEntity<List<CourseResponse>> getUserBookmarkedCourses(Authentication authentication) {
        UserDetails userDetails = (UserDetails) authentication.getPrincipal();
        Long userId = Long.parseLong(userDetails.getUsername());

        List<CourseResponse> bookmarkedCourses = bookmarkService.getUserBookmarkedCourses(userId);
        return ResponseEntity.ok(bookmarkedCourses);
    }

    /**
     * 현재 사용자의 즐겨찾기 과정 목록 페이징 조회
     * @param authentication 인증 정보
     * @param pageable 페이징 정보
     * @return 즐겨찾기한 과정 페이지
     */
    @GetMapping("/courses/paged")
    public ResponseEntity<Page<CourseResponse>> getUserBookmarkedCoursesPaged(
            Authentication authentication,
            Pageable pageable) {
        UserDetails userDetails = (UserDetails) authentication.getPrincipal();
        Long userId = Long.parseLong(userDetails.getUsername());

        Page<CourseResponse> bookmarkedCourses = bookmarkService.getUserBookmarkedCourses(userId, pageable);
        return ResponseEntity.ok(bookmarkedCourses);
    }

    /**
     * 과정 즐겨찾기 추가
     * @param authentication 인증 정보
     * @param courseId 과정 ID
     * @return 즐겨찾기 추가 결과
     */
    @PostMapping("/courses/{courseId}")
    public ResponseEntity<Map<String, Object>> addBookmark(
            Authentication authentication,
            @PathVariable Long courseId) {
        UserDetails userDetails = (UserDetails) authentication.getPrincipal();
        Long userId = Long.parseLong(userDetails.getUsername());

        boolean added = bookmarkService.addBookmark(userId, courseId);

        if (added) {
            return ResponseEntity.ok(Map.of(
                "success", true,
                "message", "과정이 즐겨찾기에 추가되었습니다.",
                "courseId", courseId
            ));
        } else {
            return ResponseEntity.ok(Map.of(
                "success", false,
                "message", "이미 즐겨찾기에 추가된 과정입니다.",
                "courseId", courseId
            ));
        }
    }

    /**
     * 과정 즐겨찾기 삭제
     * @param authentication 인증 정보
     * @param courseId 과정 ID
     * @return 즐겨찾기 삭제 결과
     */
    @DeleteMapping("/courses/{courseId}")
    public ResponseEntity<Map<String, Object>> removeBookmark(
            Authentication authentication,
            @PathVariable Long courseId) {
        UserDetails userDetails = (UserDetails) authentication.getPrincipal();
        Long userId = Long.parseLong(userDetails.getUsername());

        boolean removed = bookmarkService.removeBookmark(userId, courseId);

        if (removed) {
            return ResponseEntity.ok(Map.of(
                "success", true,
                "message", "과정이 즐겨찾기에서 제거되었습니다.",
                "courseId", courseId
            ));
        } else {
            return ResponseEntity.ok(Map.of(
                "success", false,
                "message", "즐겨찾기에 없는 과정입니다.",
                "courseId", courseId
            ));
        }
    }

    /**
     * 과정 즐겨찾기 상태 확인
     * @param authentication 인증 정보
     * @param courseId 과정 ID
     * @return 즐겨찾기 여부
     */
    @GetMapping("/courses/{courseId}/status")
    public ResponseEntity<Map<String, Object>> checkBookmarkStatus(
            Authentication authentication,
            @PathVariable Long courseId) {
        UserDetails userDetails = (UserDetails) authentication.getPrincipal();
        Long userId = Long.parseLong(userDetails.getUsername());

        boolean isBookmarked = bookmarkService.isBookmarked(userId, courseId);

        return ResponseEntity.ok(Map.of(
            "isBookmarked", isBookmarked,
            "courseId", courseId
        ));
    }

    /**
     * 사용자의 즐겨찾기 과정 수 조회
     * @param authentication 인증 정보
     * @return 즐겨찾기 과정 수
     */
    @GetMapping("/count")
    public ResponseEntity<Map<String, Object>> countUserBookmarks(Authentication authentication) {
        UserDetails userDetails = (UserDetails) authentication.getPrincipal();
        Long userId = Long.parseLong(userDetails.getUsername());

        long bookmarkCount = bookmarkService.countUserBookmarks(userId);

        return ResponseEntity.ok(Map.of(
            "count", bookmarkCount
        ));
    }
}

package com.example.course.dto;

import com.example.course.entity.Course;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

import java.time.LocalDateTime;

/**
 * 교육 과정 정보 응답을 위한 DTO
 */

// SFR-113 : 강의 즐겨찾기 기능 Test Case
//   **즐겨찾기 편집 및 등록**
//    - 즐겨찾기에 대한 조회, 추가, 삭제 기능 제공(O)
//   **즐겨찾기한 강의에 대한 간략한 정보 조회**
//    - 강의 기간, 레벨, 강사 정보 등을 간략하게 조회할 수 있는 정보 제공
//  

@Getter
@NoArgsConstructor
public class CourseResponse {
    /**
     * 과정 고유 ID
     */
    private Long id;

    /**
     * 과정 코드
     */
    private String code;

    /**
     * 과정명
     */
    private String name;

    /**
     * 과정 설명
     */
    private String description;

    /**
     * 학습 목표
     */
    private String learningObjectives;

    /**
     * 총 소요 시간(분)
     */
    private Integer totalMinutes;

    /**
     * 최대 수강 인원
     */
    private Integer maxEnrollment;

    /**
     * 최소 수강 인원
     */
    private Integer minEnrollment;

    /**
     * 활성화 여부
     */
    private boolean active;

    /**
     * 카테고리 ID
     */
    private Long categoryId;

    /**
     * 카테고리명
     */
    private String categoryName;

    /**
     * 과정 유형 ID
     */
    private Long typeId;

    /**
     * 과정 유형명
     */
    private String typeName;

    /**
     * 생성 일시
     */
    private LocalDateTime createdAt;

    /**
     * 수정 일시
     */
    private LocalDateTime updatedAt;

    @Builder
    private CourseResponse(Long id, String code, String name, String description,
                          String learningObjectives, Integer totalMinutes,
                          Integer maxEnrollment, Integer minEnrollment, boolean active,
                          Long categoryId, String categoryName, Long typeId, String typeName,
                          LocalDateTime createdAt, LocalDateTime updatedAt) {
        this.id = id;
        this.code = code;
        this.name = name;
        this.description = description;
        this.learningObjectives = learningObjectives;
        this.totalMinutes = totalMinutes;
        this.maxEnrollment = maxEnrollment;
        this.minEnrollment = minEnrollment;
        this.active = active;
        this.categoryId = categoryId;
        this.categoryName = categoryName;
        this.typeId = typeId;
        this.typeName = typeName;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
    }

    /**
     * Course 엔티티를 CourseResponse DTO로 변환
     */
    public static CourseResponse from(Course course) {
        return CourseResponse.builder()
                .id(course.getId())
                .code(course.getCode())
                .name(course.getName())
                .description(course.getDescription())
                .learningObjectives(course.getLearningObjectives())
                .totalMinutes(course.getTotalMinutes())
                .maxEnrollment(course.getMaxEnrollment())
                .minEnrollment(course.getMinEnrollment())
                .active(course.isActive())
                .categoryId(course.getCategory() != null ? course.getCategory().getId() : null)
                .categoryName(course.getCategory() != null ? course.getCategory().getName() : null)
                .typeId(course.getType() != null ? course.getType().getId() : null)
                .typeName(course.getType() != null ? course.getType().getName() : null)
                .createdAt(course.getCreatedAt())
                .updatedAt(course.getUpdatedAt())
                .build();
    }
}

package com.example.course.entity;

import com.example.common.entity.BaseTimeEntity;
import jakarta.persistence.*;
import lombok.*;

import java.util.ArrayList;
import java.util.List;

/**
 * 교육과정 엔티티
 * 교육과정의 기본 정보를 관리
 */
// SFR-113 : 강의 즐겨찾기 기능 Test Case
//   **즐겨찾기 편집 및 등록**
//    - 즐겨찾기에 대한 조회, 추가, 삭제 기능 제공(O)
//   **즐겨찾기한 강의에 대한 간략한 정보 조회**
//    - 강의 기간, 레벨, 강사 정보 등을 간략하게 조회할 수 있는 정보 제공
//  
@Entity
@Table(name = "courses")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Course extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // 기존에 없던 레벨 컬럼 추가 25.09.16
    @Column(nullable = false, length = 30)
    private String courseLevel;

    // 기존에 없던 강사정보 컬럼 추가 25.09.16
    @Column(nullable = false,  length = 30)
    private String instructorInfo;

    /**
     * 과정 코드
     */
    @Column(nullable = false, unique = true, length = 30)
    private String code;

    /**
     * 과정명
     */
    @Column(nullable = false, length = 200)
    private String name;

    /**
     * 과정 설명
     */
    @Column(length = 2000)
    private String description;

    /**
     * 과정 학습 목표
     */
    @Column(length = 1000)
    private String learningObjectives;

    /**
     * 총 교육 시간 (분 단위)
     */
    private Integer totalMinutes;

    /**
     * 활성화 여부
     */
    @Column(nullable = false)
    private boolean active = true;

    /**
     * 최대 수강 인원
     */
    private Integer maxEnrollment;

    /**
     * 최소 수강 인원
     */
    private Integer minEnrollment;

    /**
     * 과정 유형
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "type_id")
    private CourseType type;

    /**
     * 과정 카테고리
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "category_id")
    private CourseCategory category;

    /**
     * 교육 차수/기수 목록
     */
    @OneToMany(mappedBy = "course")
    @Builder.Default
    private List<CourseSession> sessions = new ArrayList<>();

    /**
     * 총 등록된 수강생 수
     */
    private int enrollmentCount = 0;

    /**
     * 수강생 등록 시 수강생 수 증가
     */
    public void incrementEnrollmentCount() {
        this.enrollmentCount++;
    }

    /**
     * 수강생 취소 시 수강생 수 감소
     */
    public void decrementEnrollmentCount() {
        if (this.enrollmentCount > 0) {
            this.enrollmentCount--;
        }
    }
}

package com.example.course.repository;

import com.example.course.entity.Course;
import com.example.course.entity.CourseBookmark;
import com.example.user.entity.User;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 과정 즐겨찾기 관련 데이터 액세스를 위한 리포지토리
 */
// SFR-113 : 강의 즐겨찾기 기능 Test Case
//   **즐겨찾기 편집 및 등록**
//    - 즐겨찾기에 대한 조회, 추가, 삭제 기능 제공(O)
//   **즐겨찾기한 강의에 대한 간략한 정보 조회**
//    - 강의 기간, 레벨, 강사 정보 등을 간략하게 조회할 수 있는 정보 제공
//  
@Repository
public interface CourseBookmarkRepository extends JpaRepository<CourseBookmark, Long> {

    /**
     * 사용자가 즐겨찾기한 과정 북마크 목록 조회
     * @param user 사용자
     * @return 북마크 목록
     */
    List<CourseBookmark> findByUser(User user);

    /**
     * 사용자가 즐겨찾기한 과정 북마크 목록 페이징 조회
     * @param user 사용자
     * @param pageable 페이징 정보
     * @return 북마크 페이지
     */
    Page<CourseBookmark> findByUser(User user, Pageable pageable);

    /**
     * 특정 사용자의 특정 과정 북마크 조회
     * @param user 사용자
     * @param course 과정
     * @return 북마크 (Optional)
     */
    Optional<CourseBookmark> findByUserAndCourse(User user, Course course);

    /**
     * 특정 사용자가 특정 과정을 즐겨찾기했는지 확인
     * @param user 사용자
     * @param course 과정
     * @return 즐겨찾기 여부
     */
    boolean existsByUserAndCourse(User user, Course course);

    /**
     * 특정 사용자의 즐겨찾기 과정 수 조회
     * @param user 사용자
     * @return 즐겨찾기 과정 수
     */
    long countByUser(User user);

    /**
     * 특정 과정을 즐겨찾기한 수 조회
     * @param course 과정
     * @return 즐겨찾기 수
     */
    long countByCourse(Course course);

    /**
     * 특정 사용자의 북마크 삭제
     * @param user 사용자
     * @param course 과정
     */
    void deleteByUserAndCourse(User user, Course course);
}

package com.example.course.repository;

import com.example.course.entity.Course;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 교육과정 Repository
 */
// SFR-113 : 강의 즐겨찾기 기능 Test Case
//   **즐겨찾기 편집 및 등록**
//    - 즐겨찾기에 대한 조회, 추가, 삭제 기능 제공(O)
//   **즐겨찾기한 강의에 대한 간략한 정보 조회**
//    - 강의 기간, 레벨, 강사 정보 등을 간략하게 조회할 수 있는 정보 제공
//  
@Repository
public interface CourseRepository extends JpaRepository<Course, Long> {

    /**
     * 코드로 교육과정 조회
     * 
     * @param code 교육과정 코드
     * @return 교육과정 Optional 객체
     */
    Optional<Course> findByCode(String code);

    /**
     * 활성화된 교육과정 목록 조회
     * 
     * @return 활성화된 교육과정 목록
     */
    List<Course> findByActiveTrue();

    /**
     * 카테고리별 교육과정 목록 조회
     * 
     * @param categoryId 카테고리 ID
     * @return 해당 카테고리에 속한 교육과정 목록
     */
    List<Course> findByCategoryId(Long categoryId);

    /**
     * 교육과정 유형별 교육과정 목록 조회
     * 
     * @param typeId 교육과정 유형 ID
     * @return 해당 유형의 교육과정 목록
     */
    List<Course> findByTypeId(Long typeId);

    /**
     * 수강생 수 기준 인기 과정 조회 (활성화된 과정만)
     */
    List<Course> findByActiveTrueOrderByEnrollmentCountDesc();

    /**
     * 최신 과정 조회 (생성일 기준, 활성화된 과정만)
     */
    List<Course> findByActiveTrueOrderByCreatedAtDesc();

    /**
     * 특정 카테고리 목록에 속한 활성화된 과정 목록 조회
     */
    List<Course> findByCategoryIdInAndActiveTrue(List<Long> categoryIds);
}

package com.example.course.service;

import com.example.common.exception.EntityNotFoundException;
import com.example.course.dto.CourseResponse;
import com.example.course.entity.Course;
import com.example.course.entity.CourseBookmark;
import com.example.course.repository.CourseBookmarkRepository;
import com.example.course.repository.CourseRepository;
import com.example.user.entity.User;
import com.example.user.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

/**
 * 과정 즐겨찾기 관련 비즈니스 로직을 처리하는 서비스
 */

// SFR-113 : 강의 즐겨찾기 기능 Test Case
//   **즐겨찾기 편집 및 등록**
//    - 즐겨찾기에 대한 조회, 추가, 삭제 기능 제공(O)
//   **즐겨찾기한 강의에 대한 간략한 정보 조회**
//    - 강의 기간, 레벨, 강사 정보 등을 간략하게 조회할 수 있는 정보 제공
//  

@Service
@RequiredArgsConstructor
@Transactional(readOnly = true)
public class CourseBookmarkService {

    private final CourseBookmarkRepository bookmarkRepository;
    private final CourseRepository courseRepository;
    private final UserRepository userRepository;

    /**
     * 사용자의 즐겨찾기 과정 목록 조회
     * @param userId 사용자 ID
     * @return 즐겨찾기한 과정 목록
     */
    public List<CourseResponse> getUserBookmarkedCourses(Long userId) {
        User user = userRepository.findById(userId)
                .orElseThrow(() -> new EntityNotFoundException("사용자를 찾을 수 없습니다. ID: " + userId));

        return bookmarkRepository.findByUser(user).stream()
                .map(bookmark -> CourseResponse.from(bookmark.getCourse()))
                .collect(Collectors.toList());
    }

    /**
     * 사용자의 즐겨찾기 과정 목록 페이징 조회
     * @param userId 사용자 ID
     * @param pageable 페이징 정보
     * @return 즐겨찾기한 과정 페이지
     */
    public Page<CourseResponse> getUserBookmarkedCourses(Long userId, Pageable pageable) {
        User user = userRepository.findById(userId)
                .orElseThrow(() -> new EntityNotFoundException("사용자를 찾을 수 없습니다. ID: " + userId));

        return bookmarkRepository.findByUser(user, pageable)
                .map(bookmark -> CourseResponse.from(bookmark.getCourse()));
    }

    /**
     * 과정 즐겨찾기 추가
     * @param userId 사용자 ID
     * @param courseId 과정 ID
     * @return 즐겨찾기 성공 여부
     */
    @Transactional
    public boolean addBookmark(Long userId, Long courseId) {
        User user = userRepository.findById(userId)
                .orElseThrow(() -> new EntityNotFoundException("사용자를 찾을 수 없습니다. ID: " + userId));

        Course course = courseRepository.findById(courseId)
                .orElseThrow(() -> new EntityNotFoundException("과정을 찾을 수 없습니다. ID: " + courseId));

        // 이미 즐겨찾기한 경우 중복 저장 방지
        if (bookmarkRepository.existsByUserAndCourse(user, course)) {
            return false;
        }

        CourseBookmark bookmark = CourseBookmark.builder()
                .user(user)
                .course(course)
                .build();

        bookmarkRepository.save(bookmark);
        return true;
    }

    /**
     * 과정 즐겨찾기 삭제
