    @Column(nullable = false)
    private String name;

    /**
     * 사용자 역할 (권한)
     */
    @Column(nullable = false)
    @Enumerated(EnumType.STRING)
    private UserRole role;

    /**
     * 계정 활성화 여부
     */
    @Column(nullable = false)
    private boolean enabled = true;

    /**
     * 사용자 생성자
     * @param email 사용자 이메일
     * @param password 사용자 비밀번호
     * @param name 사용자 이름
     * @param role 사용자 역할
