        this.email = email;
        this.password = password;
        this.name = name;
        this.role = role;
    }

    /**
     * 사용자의 권한 목록을 반환
     * @return 사용자의 권한 목록
     */
    @Override
    public Collection<? extends GrantedAuthority> getAuthorities() {
        return List.of(new SimpleGrantedAuthority(role.name()));
    }

    /**
     * 사용자의 로그인 ID를 반환 (이메일 사용)
     * @return 사용자 이메일
     */
    @Override
    public String getUsername() {
        return email;
    }

    /**
     * 계정이 만료되지 않았는지 확인
     * @return 계정 만료 여부
     */
    @Override
    public boolean isAccountNonExpired() {
        return true;
    }

    /**
     * 계정이 잠겨있지 않은지 확인
     * @return 계정 잠금 여부
     */
    @Override
    public boolean isAccountNonLocked() {
        return true;
    }

    /**
     * 자격 증명이 만료되지 않았는지 확인
     * @return 자격 증명 만료 여부
     */
    @Override
    public boolean isCredentialsNonExpired() {
        return true;
    }

    /**
     * 계정이 활성화되어 있는지 확인
     * @return 계정 활성화 여부
     */
    @Override
    public boolean isEnabled() {
        return enabled;
    }

    /**
     * 사용자 비밀번호를 업데이트
     * @param password 새로운 비밀번호
     */
    public void updatePassword(String password) {
        this.password = password;
    }

    /**
     * 사용자 계정을 비활성화
     */
    public void disable() {
        this.enabled = false;
    }
}

